export const categoryGuides: Record<string, CategoryGuide> = Object.fromEntries(
  guides.map(([id, concept, when, installation, care]) => [
    id,
    {
      concept: bilingual(concept),
      when: bilingual(when),
      areas: [bilingual(installation), bilingual(care)],
    },
  ]),
);

export const subcategoryConcepts: Record<string, Localized> =
  Object.fromEntries(
    Object.entries(categoryGuides).flatMap(([id, guide]) => [
      [`${id}-installation`, guide.areas[0]],
      [`${id}-care`, guide.areas[1]],
    ]),
  );
